def fig_entry(name):
    e = fig['sets'].get(name) or fig['single'].get(name)
    out = {'nodeId': e['id'], 'key': e['key']}
    if 'defaultVariant' in e: out['defaultVariant'] = e['defaultVariant']
    if 'props' in e:
        out['properties'] = {k: ({'options': v['options'], 'default': v['default']} if v['type'] == 'variant' else {'type': v['type'], 'default': v['default'], 'propertyKey': v['key']}) for k, v in e['props'].items()}
    out['size'] = e.get('size')
    return out

comps = {}
for name, sp in SPEC.items():
    c = {}
    if sp.get('part'): c['partOf'] = sp['part']; c['note'] = f'직접 쓰지 말고 {sp["part"]}를 쓴다.'
    if sp.get('status'): c['status'] = sp['status']
    for k in ('use', 'avoid'):
        if sp.get(k): c[k] = sp[k]
    c['figma'] = fig_entry(name)
    for k in ('nested', 'parts', 'states', 'code', 'related'):
        if sp.get(k): c[k] = sp[k]
    comps[name] = c

